import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  Output,
  ViewEncapsulation,
} from '@angular/core';
import { ENTER } from '@questrade/allspark-angular-components/core/utils';
import { QCardVariant } from './types/card-variant.type';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-card',
  template: '<ng-content />',
  styleUrls: ['./card.component.scss'],
})
export class QCardComponent {
  @Output() readonly selectedChange = new EventEmitter<boolean>();

  @Input({ transform: booleanAttribute }) selected = false;
  @Input({ transform: booleanAttribute }) selectable = false;
  @Input() variant: QCardVariant = 'outline';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-card';

  @HostBinding('attr.tabindex') get hostTabindex(): number | null {
    return this.selectable ? 0 : null;
  }

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-card',
      this.selectable && 'q-card-selectable',
      this.selected && 'q-card-selected',
      `q-card-${this.variant}`,
      'q-focus-indicator-inset',
    ]
      .filter(Boolean)
      .join(' ');
  }

  @HostListener('click', ['$event']) _onCardClick(event: Event): void {
    if (!this.selectable) return;

    event.stopPropagation();

    this.selected = !this.selected;

    this.selectedChange.emit(this.selected);
  }

  @HostListener('keydown', ['$event']) _onKeyDown(event: KeyboardEvent): void {
    if (event.code === ENTER) this._onCardClick(event);
  }
}
